import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:intl/intl.dart';import '../../../core/providers/app_providers.dart';import '../../../core/domain/care_entities.dart';
class ReminderHistoryScreen extends ConsumerWidget{const ReminderHistoryScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final c=ref.watch(appControllerProvider);final events=c.items('care_logs').map(CareLog.fromMap).where((e)=>e.type=='Reminder completed'||e.type=='Reminder skipped').toList()..sort((a,b)=>b.at.compareTo(a.at));return Scaffold(appBar:AppBar(title:const Text('Reminder history')),body:events.isEmpty?const Center(child:Text('Completed reminder activity will appear here.')):ListView(padding:const EdgeInsets.all(16),children:events.map((e)=>Card(child:ListTile(title:Text(e.title),subtitle:Text('${e.type} · ${DateFormat.yMMMd().add_jm().format(e.at)}')))).toList()));}}
